T length_squared = result.x * result.x + result.y * result.y + result.z * result.z;
if (length_squared > std::numeric_limits<T>::epsilon()) {
  T length = std::sqrt(length_squared);
  result.x /= length;
  result.y /= length;
  result.z /= length;
} else {
  result.x = result.y = result.z = static_cast<T>(0);
}
return result;

